using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using Petrichor.Core;using Windows.UI.Xaml;using Windows.UI.Xaml.Controls;using Windows.UI.Xaml.Navigation;using Windows.Storage;namespace Petrichor.App.Pages {public sealed partial class AlbumPage : MusicPage {public AlbumPage(){InitializeComponent();}
private AlbumDetails album;public int TrackCount=>album?.Tracks.Count??0;
protected override async Task LoadAsync(object p){album=await App.Api.GetAlbumAsync(Convert.ToInt64(p),Token);Title.Text=album.Album.Name;Cover.Source=MusicItem.Image(album.Album.CoverUrl);Subtitle.Text=string.Join(" / ",album.Artists.Select(a=>a.Name))+" · "+album.PublishedAt.ToString("yyyy.MM.dd");Description.Text=album.Description??"";Tracks.ItemsSource=album.Tracks.Select(MusicItem.From).ToList();}
private void ArtistClick(object s,RoutedEventArgs e){if(album?.Artists.Count>0)Shell.Current.Navigate(typeof(ArtistPage),album.Artists[0].Id);}
private async void PlayAll(object s,RoutedEventArgs e){if(album!=null)await ExecuteAsync(()=>PlayTracksAsync(album.Tracks));}
private async void SaveClick(object s,RoutedEventArgs e){if(!App.Api.IsLoggedIn){Shell.Current.Navigate(typeof(LoginPage));return;}if(album!=null)await ExecuteAsync(async()=>{await App.Api.SetAlbumSavedAsync(album.Album.Id,true,Token);Shell.Current.Notify("已收藏专辑。");});}}}
